import {RANKS,SUITS} from './engine.mjs';
import {MAX_IMAGE_BYTES,imageMime,localOrigin,recognizeScreenshot,listVisionModels,differenceHash,screenshotReuse,applyScreenshotReview} from './screenshot.mjs?v=2.1.0';

const html=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clamp=(v,lo,hi)=>Math.max(lo,Math.min(hi,v));
const button=(label,action,cls='',disabled=false)=>`<button type="button" class="btn ${cls}" data-shot-action="${action}" ${disabled?'disabled':''}>${label}</button>`;
const hash=async bytes=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(n=>n.toString(16).padStart(2,'0')).join('');

export function createScreenshotImporter({getState,saveConnection,onApply,toast}){
 const root=document.createElement('dialog');root.id='screenshot-modal';root.className='screenshot-modal';root.setAttribute('aria-label','Read screenshot');document.body.appendChild(root);
 let session=null,serial=0,drag=null;
 const picker=document.createElement('input');picker.type='file';picker.id='shot-file';picker.accept='image/png,image/jpeg,image/webp';picker.hidden=true;picker.addEventListener('change',()=>{if(picker.files[0])loadFile(picker.files[0]);});
 const alive=id=>session?.id===id&&root.open;
 const stop=()=>{session?.controller?.abort();};
 function cleanup(){stop();if(session?.url)URL.revokeObjectURL(session.url);session=null;drag=null;serial++;}
 root.addEventListener('close',cleanup);
 function open(game='blackjack'){
  if(root.open)return;const ai=getState().ai;
  session={id:++serial,game,rows:[],notes:'',crop:{x:0,y:0,w:1,h:1},roundMode:'update',ackSimilar:false,confirmed:false,endpoint:ai.endpoint,model:ai.visionModel||'',models:[],status:'',error:'',busy:false,applying:false,cropVersion:0};
  render();root.showModal();
 }
 function zones(){return session.game==='poker'?[['hero','Your hand'],['board','Board'],['opponent','Opponent 1'],['other','Dead cards'],['ignore','Ignore']]:[['hero','Your hand'],['dealer','Dealer upcard'],['other','Other seen'],['ignore','Ignore']];}
 function rowView(r,i){const uncertain=r.uncertain||!r.rank||session.game==='poker'&&!r.suit;
  return `<div class="shot-card-row ${uncertain?'is-uncertain':''}" data-shot-row="${r.id}"><span class="shot-card-glyph ${r.suit==='h'||r.suit==='d'?'red':''}">${html(r.rank||'?')}<small>${r.suit?SUITS['shdc'.indexOf(r.suit)]:'?'}</small></span><div class="shot-row-fields"><label><span>Group</span><select class="form-select" data-shot-card-field="zone" aria-label="Card ${i+1} group">${zones().map(([k,v])=>`<option value="${k}" ${r.zone===k?'selected':''}>${v}</option>`).join('')}</select></label><label><span>Rank</span><select class="form-select" data-shot-card-field="rank" aria-label="Card ${i+1} rank"><option value="">Unknown</option>${RANKS.map(k=>`<option ${r.rank===k?'selected':''}>${k}</option>`).join('')}</select></label><label><span>Suit${session.game==='blackjack'?' · optional':''}</span><select class="form-select" data-shot-card-field="suit" aria-label="Card ${i+1} suit"><option value="">Unknown</option>${['shdc'][0].split('').map((k,j)=>`<option value="${k}" ${r.suit===k?'selected':''}>${SUITS[j]}</option>`).join('')}</select></label></div>${session.game==='blackjack'&&r.zone==='other'?`<label class="shot-new-card"><input type="checkbox" data-shot-card-field="newInShoe" ${r.newInShoe?'checked':''}>New to shoe</label>`:''}<button type="button" class="icon-btn shot-remove" data-shot-action="remove-card" data-shot-id="${r.id}" aria-label="Remove card ${i+1}">×</button></div>`;
 }
 function reuseNotice(){if(!session.meta||session.game!=='blackjack')return '';const r=screenshotReuse(getState().screenshots,session.meta);if(r.exact)return '<div class="shot-notice amber">This image has already been applied in this shoe. You can correct the same current hand, but cannot count it as a new round or append extra observations.</div>';if(r.similar)return '<div class="shot-notice amber">This image looks similar to a previous screenshot. If you are starting a new round or adding extra cards, confirm it is a different deal below.</div>';return '';}
 function render(){const s=session;if(!s)return;const disabled=s.busy||s.applying;
  root.innerHTML=`<div class="modal-head"><div><h2>Read screenshot</h2><p class="tiny muted" style="margin:5px 0 0">Choose an image → read the cards → review before applying.</p></div><button type="button" class="icon-btn" data-shot-action="close" aria-label="Close screenshot">×</button></div><div class="modal-body shot-body"><div class="shot-image-column"><div class="shot-dropzone ${s.url?'has-image':''}" data-shot-drop>${s.url?`<div class="shot-image-wrap" data-shot-image-wrap><img src="${html(s.url)}" alt="Uploaded game screenshot" draggable="false"><div class="shot-crop" style="left:${s.crop.x*100}%;top:${s.crop.y*100}%;width:${s.crop.w*100}%;height:${s.crop.h*100}%"></div></div>`:'<div class="shot-placeholder"><span aria-hidden="true">▧</span><h3>Drop your game screenshot here</h3><p>PNG, JPEG or WebP · up to 12 MB<br>You can also paste an image with Ctrl+V.</p></div>'}</div><div class="lab-row wrap shot-image-tools">${button(s.url?'Choose another image':'Choose image','choose','btn-outline-secondary')}${button('Paste image','paste','btn-ghost-secondary')}${s.url?button('Whole image','reset-crop','btn-ghost-secondary',disabled):''}</div>${s.url?`<p class="tiny muted">${html(s.name)} · ${s.image.naturalWidth} × ${s.image.naturalHeight}<br>Drag over the image to crop the table. Only the selected region is sent to your model.</p><details class="shot-crop-details"><summary>Precise crop</summary><div class="shot-crop-fields">${[['x','Left'],['y','Top'],['w','Width'],['h','Height']].map(([k,label])=>`<label>${label} %<input class="form-control" type="number" data-shot-crop="${k}" min="${k==='w'||k==='h'?5:0}" max="100" step="1" value="${Math.round(s.crop[k]*100)}" ${disabled?'disabled':''}></label>`).join('')}</div></details>`:''}<details class="shot-connection" ${!s.model?'open':''}><summary>Vision connection${s.model?' · '+html(s.model):' · choose a local model'}</summary><div class="field"><label for="shot-endpoint">Local Ollama origin</label><input class="form-control" id="shot-endpoint" data-shot-config="endpoint" type="url" value="${html(s.endpoint)}" placeholder="http://127.0.0.1:11434" ${disabled?'disabled':''}></div><div class="field"><label for="shot-model">Installed vision model</label><input class="form-control" id="shot-model" data-shot-config="model" list="shot-models" value="${html(s.model)}" placeholder="Choose a model that supports images" maxlength="120" ${disabled?'disabled':''}><datalist id="shot-models">${s.models.map(m=>`<option value="${html(m)}"></option>`).join('')}</datalist></div><div class="lab-row wrap">${button('Find vision models','models','btn-outline-secondary small',disabled)}${button('Save connection','save-connection','btn-ghost-secondary small',disabled)}</div><p class="tiny muted">Requires a running Ollama service and an installed vision model. Images go to this localhost endpoint. Browser origin permissions may be needed. You can also enter cards manually beside the image.</p></details><div class="shot-read-actions">${s.busy?button('Cancel recognition','cancel','btn-outline-secondary'):button(s.rows.length?'Read cards again':'Read cards with local AI','read','primary',!s.image||s.applying)}</div><p class="shot-status" role="status">${html(s.status)}</p>${s.error?`<div class="shot-notice error" role="alert">${html(s.error)}</div>`:''}</div><div class="shot-review-column"><div class="lab-row between"><h3>Review the visible cards</h3><select class="form-select shot-game" data-shot-config="game" aria-label="Screenshot game" ${disabled?'disabled':''}><option value="blackjack" ${s.game==='blackjack'?'selected':''}>Blackjack</option><option value="poker" ${s.game==='poker'?'selected':''}>Texas Hold’em</option></select></div><p class="tiny muted">Check every rank and suit against the image. Hidden cards are never inferred. Set decorative or unrelated cards to Ignore.</p>${reuseNotice()}${s.notes?`<div class="shot-notice">Model note: ${html(s.notes)}</div>`:''}<div class="shot-card-list">${s.rows.length?s.rows.map(rowView).join(''):'<div class="shot-review-empty">No cards read yet.<br>Use local AI, or add the visible cards manually.</div>'}</div>${button('+ Add a card','add-card','btn-outline-secondary small',!s.image||disabled||s.rows.length>=48)}${s.game==='blackjack'?`<div class="field shot-round-mode"><label for="shot-round-mode">How should this screenshot be applied?</label><select class="form-select" id="shot-round-mode" data-shot-config="roundMode" ${disabled?'disabled':''}><option value="update" ${s.roundMode==='update'?'selected':''}>Update the current round</option><option value="new" ${s.roundMode==='new'?'selected':''}>Start a new round</option></select><small>Update replaces your current hand and upcard. New round archives the previous hand; round-shuffled games start a fresh shoe.</small></div><div class="shot-notice">Only cards checked “New to shoe” under Other seen are appended to the observation log. Leave previously counted cards unchecked. The action calculator assumes a US dealer peek has ruled out blackjack.</div>${s.meta&&screenshotReuse(getState().screenshots,s.meta).similar?`<label class="shot-check"><input type="checkbox" data-shot-config="ackSimilar" ${s.ackSimilar?'checked':''}>This is a different deal from the similar image.</label>`:''}`:'<div class="shot-notice" style="margin-top:16px">This replaces your hole cards, board, known opponent, and dead cards. Pot, call price, and opponent count stay as entered. Poker needs a suit for every included card.</div>'}<label class="shot-check shot-confirm"><input type="checkbox" data-shot-config="confirmed" ${s.confirmed?'checked':''} ${disabled?'disabled':''}>I checked these cards against the screenshot.</label><p class="tiny muted">Images are kept in memory for this review and are not included in backups. Only fingerprints are saved to help detect repeats.</p></div></div><div class="modal-foot">${button('Cancel','close','ghost')}${button('Apply reviewed cards','apply','btn-outline-secondary',disabled||!s.confirmed||!s.rows.length)}${button(s.applying?'Applying…':'Apply & analyze','apply-analyze','primary',disabled||!s.confirmed||!s.rows.length)}</div>`;
  root.appendChild(picker);
 }
 async function loadFile(file){if(!session)return;stop();session.id=++serial;const id=session.id;session.controller=null;session.busy=false;session.confirmed=false;session.rows=[];session.meta=null;session.encoded=null;session.image=null;if(session.url)URL.revokeObjectURL(session.url);session.url=null;session.status='Loading image…';session.error='';render();try{
  if(!file||!file.size)throw new Error('Choose an image file.');if(file.size>MAX_IMAGE_BYTES)throw new Error('This image is larger than 12 MB. Crop or resize it before importing.');const bytes=new Uint8Array(await file.arrayBuffer());const mime=imageMime(bytes);if(!alive(id))return;
  const url=URL.createObjectURL(new Blob([bytes],{type:mime})),image=new Image();image.src=url;try{await image.decode();}catch{URL.revokeObjectURL(url);throw new Error('This image could not be decoded. Choose a valid PNG, JPEG, or WebP file.');}const fileHash=await hash(bytes);if(!alive(id)){URL.revokeObjectURL(url);return;}if(!image.naturalWidth||!image.naturalHeight||image.naturalWidth*image.naturalHeight>40000000){URL.revokeObjectURL(url);throw new Error('Use an image no larger than 40 megapixels.');}if(session.url)URL.revokeObjectURL(session.url);Object.assign(session,{url,image,name:file.name||'Pasted image',fileHash,rows:[],notes:'',crop:{x:0,y:0,w:1,h:1},cropVersion:session.cropVersion+1,meta:null,encoded:null,confirmed:false,ackSimilar:false,status:'Image ready. Crop it, read with local AI, or add cards manually.'});render();await prepare(id);
 }catch(e){if(alive(id)){session.error=e.message;session.status='';render();}}}
 async function prepare(id=session?.id){if(!alive(id)||!session.image)throw new Error('Choose an image first.');if(session.meta&&session.encoded)return {meta:session.meta,base64:session.encoded};const s=session,c={...s.crop},version=s.cropVersion,img=s.image,sw=img.naturalWidth*c.w,sh=img.naturalHeight*c.h;if(sw<24||sh<24)throw new Error('The selected region is too small. Include the complete cards.');const scale=Math.min(1,2048/Math.max(sw,sh)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(sw*scale));canvas.height=Math.max(1,Math.round(sh*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#f8f6ed';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,img.naturalWidth*c.x,img.naturalHeight*c.y,sw,sh,0,0,canvas.width,canvas.height);const dataUrl=canvas.toDataURL('image/jpeg',.93),base64=dataUrl.slice(dataUrl.indexOf(',')+1),bytes=Uint8Array.from(atob(base64),x=>x.charCodeAt(0));const sample=document.createElement('canvas');sample.width=9;sample.height=8;const sc=sample.getContext('2d',{willReadFrequently:true});sc.drawImage(canvas,0,0,9,8);const meta={fileHash:s.fileHash,cropHash:await hash(bytes),perceptualHash:differenceHash(sc.getImageData(0,0,9,8).data),cropKey:[c.x,c.y,c.w,c.h].map(v=>Math.round(v*10000)).join(',')};if(!alive(id)||session.cropVersion!==version)throw new Error('The image changed. Review the current crop and try again.');session.meta=meta;session.encoded=base64;if(!session.busy&&!session.applying)render();return {meta,base64};}
 function saveLocalConnection(){const endpoint=localOrigin(session.endpoint),model=session.model.trim();if(model.length>120)throw new Error('Use a model name of at most 120 characters.');saveConnection({endpoint,model});session.endpoint=endpoint;session.model=model;}
 function normalizeRows(rows,game){let dealer=0;return rows.map(r=>({...r,newInShoe:false,zone:game==='blackjack'?(r.zone==='dealer'&&dealer++>0?'other':['board','opponent'].includes(r.zone)?'other':r.zone):r.zone==='dealer'?'ignore':r.zone}));}
 async function read(){if(!session||session.busy||!session.image)return;const id=session.id;session.error='';try{saveLocalConnection();if(!session.model)throw new Error('Choose an installed vision model under Vision connection. You can also add cards manually.');session.busy=true;session.confirmed=false;session.status='Reading visible cards with your local model…';session.controller=new AbortController();render();const timer=setTimeout(()=>session?.id===id&&session.controller?.abort(),90000);try{const image=await prepare(id);const result=await recognizeScreenshot({endpoint:session.endpoint,model:session.model,base64:image.base64,game:session.game,signal:session.controller.signal});if(!alive(id))return;if(result.game!=='unknown')session.game=result.game;session.rows=normalizeRows(result.cards,session.game);session.notes=result.notes;session.status=result.cards.length?'Cards read. Check and correct every card before applying.':'No face-up cards were identified. Try a tighter crop or add cards manually.';}finally{clearTimeout(timer);}}
  catch(e){if(alive(id)){session.error=session.controller?.signal.aborted?'Recognition canceled or timed out. You can retry or enter the cards manually.':e instanceof TypeError?'Could not reach your local Ollama service. Check that it is running and permits this page’s origin, or use the local app. Manual card review still works.':e.message;session.status='';}}
  finally{if(alive(id)){session.busy=false;session.controller=null;render();}}
 }
 async function findModels(){if(!session||session.busy)return;const id=session.id;session.busy=true;session.error='';session.status='Checking installed models for image support…';session.controller=new AbortController();render();const timer=setTimeout(()=>session?.id===id&&session.controller?.abort(),20000);try{const names=await listVisionModels({endpoint:session.endpoint,signal:session.controller.signal});if(!alive(id))return;session.models=names;if(!session.model&&names.length)session.model=names[0];session.status=names.length?`Found ${names.length} vision model${names.length>1?'s':''}. Select one under Vision connection.`:'No installed vision models were found. Install a vision model in Ollama, or review cards manually.';}catch(e){if(alive(id))session.error=session.controller?.signal.aborted?'Model check canceled or timed out.':'Could not list local vision models. Check your Ollama service and browser origin permissions.';}finally{clearTimeout(timer);if(alive(id)){session.busy=false;session.controller=null;render();}}}
 async function apply(analyze){if(!session||session.busy||session.applying||!session.confirmed)return;const id=session.id;session.applying=true;session.error='';render();try{const {meta}=await prepare(id);if(!alive(id))return;const result=applyScreenshotReview(getState(),{game:session.game,rows:session.rows,roundMode:session.roundMode,ackSimilar:session.ackSimilar,meta});if(analyze&&!result.canAnalyze)throw new Error('This blackjack hand is bust or the shoe has fewer than 24 unseen cards. Use Apply reviewed cards to track it without an action simulation.');root.close();onApply(result,analyze);}catch(e){if(alive(id)){session.applying=false;session.error=e.message;render();}}}
 async function pasteClipboard(){try{if(!navigator.clipboard?.read)throw new Error('unsupported');const items=await navigator.clipboard.read();for(const item of items){const type=item.types.find(t=>['image/png','image/jpeg','image/webp'].includes(t));if(type){const blob=await item.getType(type);await loadFile(new File([blob],'Pasted screenshot.'+type.split('/')[1],{type}));return;}}throw new Error('No image');}catch{if(session){session.error='Paste an image with Ctrl+V, or choose an image file. The clipboard may require browser permission.';render();}}}
 root.addEventListener('click',e=>{const b=e.target.closest('[data-shot-action]');if(!b||b.disabled||!session)return;const action=b.dataset.shotAction;try{
  if(action==='close'){root.close();return;}if(action==='choose'){picker.value='';picker.click();return;}if(action==='paste'){pasteClipboard();return;}if(action==='read'){read();return;}if(action==='models'){findModels();return;}if(action==='cancel'){stop();return;}if(action==='save-connection'){saveLocalConnection();session.status='Vision connection saved.';session.error='';render();return;}
  if(action==='reset-crop'){session.crop={x:0,y:0,w:1,h:1};cropChanged();return;}
  if(action==='add-card'){const own=session.rows.filter(r=>r.zone==='hero').length,zone=own<2?'hero':session.game==='blackjack'?(session.rows.some(r=>r.zone==='dealer')?'other':'dealer'):'board';session.rows.push({id:Math.max(0,...session.rows.map(r=>r.id))+1,rank:null,suit:null,zone,uncertain:true,newInShoe:false});session.confirmed=false;render();return;}
  if(action==='remove-card'){session.rows=session.rows.filter(r=>r.id!==Number(b.dataset.shotId));session.confirmed=false;render();return;}if(action==='apply'||action==='apply-analyze'){apply(action==='apply-analyze');return;}
 }catch(err){session.error=err.message;render();}});
 root.addEventListener('input',e=>{if(session&&['endpoint','model'].includes(e.target.dataset.shotConfig))session[e.target.dataset.shotConfig]=e.target.value;});
 root.addEventListener('change',e=>{if(!session)return;const el=e.target;if(el.id==='shot-file')return;const key=el.dataset.shotConfig;if(key){if(['confirmed','ackSimilar'].includes(key))session[key]=el.checked;else session[key]=el.value;if(key==='game'){session.rows=normalizeRows(session.rows,session.game);session.confirmed=false;}if(!['endpoint','model'].includes(key))render();return;}const field=el.dataset.shotCardField;if(field){const id=Number(el.closest('[data-shot-row]').dataset.shotRow),r=session.rows.find(x=>x.id===id);if(r){r[field]=field==='newInShoe'?el.checked:el.value||null;if(field==='rank'||field==='suit')r.uncertain=false;session.confirmed=false;render();}return;}const crop=el.dataset.shotCrop;if(crop){const c=session.crop;c[crop]=Number(el.value)/100;c.x=clamp(c.x,0,.95);c.y=clamp(c.y,0,.95);c.w=clamp(c.w,.05,1-c.x);c.h=clamp(c.h,.05,1-c.y);cropChanged();}});
 function cropChanged(){if(!session)return;session.cropVersion++;const id=session.id,version=session.cropVersion;session.meta=null;session.encoded=null;session.confirmed=false;session.ackSimilar=false;render();prepare().catch(e=>{if(alive(id)&&session.cropVersion===version){session.error=e.message;render();}});}
 root.addEventListener('dragover',e=>{if(e.target.closest('[data-shot-drop]')){e.preventDefault();e.dataTransfer.dropEffect='copy';}});
 root.addEventListener('drop',e=>{if(e.target.closest('[data-shot-drop]')){e.preventDefault();if(e.dataTransfer.files[0])loadFile(e.dataTransfer.files[0]);}});
 root.addEventListener('pointerdown',e=>{const wrap=e.target.closest('[data-shot-image-wrap]');if(!wrap||!session||session.busy||session.applying||e.button!==0)return;e.preventDefault();const b=wrap.getBoundingClientRect();drag={id:e.pointerId,wrap,b,start:{x:clamp((e.clientX-b.left)/b.width,0,1),y:clamp((e.clientY-b.top)/b.height,0,1)},old:{...session.crop}};wrap.setPointerCapture(e.pointerId);});
 root.addEventListener('pointermove',e=>{if(!drag||!session||e.pointerId!==drag.id)return;const x=clamp((e.clientX-drag.b.left)/drag.b.width,0,1),y=clamp((e.clientY-drag.b.top)/drag.b.height,0,1),crop={x:Math.min(x,drag.start.x),y:Math.min(y,drag.start.y),w:Math.abs(x-drag.start.x),h:Math.abs(y-drag.start.y)};session.crop=crop;const frame=drag.wrap.querySelector('.shot-crop');Object.assign(frame.style,{left:crop.x*100+'%',top:crop.y*100+'%',width:crop.w*100+'%',height:crop.h*100+'%'});});
 const endDrag=e=>{if(!drag||!session||e.pointerId!==drag.id)return;if(session.crop.w<.03||session.crop.h<.03)session.crop=drag.old;drag=null;cropChanged();};root.addEventListener('pointerup',endDrag);root.addEventListener('pointercancel',endDrag);
 return {open,loadFile,isOpen:()=>root.open,close:()=>root.close()};
}
